<?php $title='Lịch dạy giảng viên';include dirname(__DIR__).'/layout/header.php';?><div class="toolbar"><h2>Lịch dạy giảng viên</h2><form><input type="hidden" name="r" value="teacher/dashboard"><select name="semester_id" onchange="this.form.submit()"><option value="0">Tất cả học kỳ</option><?php foreach($semesters as $s):?><option value="<?=$s['id']?>" <?=$semesterId==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></form></div><div class="card"><h3>Lịch theo thứ</h3><div class="schedule"><?php for($day=2;$day<=8;$day++):?><div class="day"><h4><?= $day===8?'Chủ nhật':'Thứ '.$day ?></h4><?php $has=false;foreach($schedule as $x)if((int)$x['weekday']===$day){$has=true;?><div class="slot"><b><?=e($x['start_period'].'-'.$x['end_period'])?></b><br><?=e($x['course_code'])?><br><?=e($x['class_code'])?><br><?=e($x['room'])?><br><span class="muted"><?=e($x['semester_name'])?></span></div><?php } ?><?php if(!$has):?><div class="empty">Không có tiết</div><?php endif;?></div><?php endfor;?></div></div><div class="card"><h3>Các lớp được phân công</h3><table><tr><th>Lớp</th><th>Học phần</th><th>Học kỳ</th><th>Lịch</th><th>Đã đăng ký</th><th></th></tr><?php foreach($classes as $c):?><tr><td><?=e($c['class_code'])?></td><td><?=e($c['course_code'].' - '.$c['course_name'])?></td><td><?=e($c['semester_name'])?></td><td>Thứ <?=e($c['weekday'])?> · Tiết <?=e($c['start_period'])?>-<?=e($c['end_period'])?> · <?=e($c['room'])?></td><td><?=e($c['registered_count'].'/'.$c['max_students'])?></td><td><a class="btn small" href="<?=e(BASE_URL)?>?r=teacher/class&id=<?=$c['id']?>">Danh sách SV</a></td></tr><?php endforeach;?></table></div><?php include dirname(__DIR__).'/layout/footer.php';?>
